#!/usr/bin/env bash
# Read-only: data check for the QA location-count flow - opportunities with a blank count, quotes whose count differs from their opportunity, evergreen contracts, plan assets not linked to a contract
q() { sf data query --query "$1" --target-org target --json 2>/dev/null | jq -c '[.result.records[]? | del(.attributes)]'; }
n() { sf data query --query "$1" --target-org target --json 2>/dev/null | jq -r '.result.totalSize'; }
echo "OPPS total $(n "SELECT COUNT() FROM Opportunity WHERE AccountId != null"), blank count $(n "SELECT COUNT() FROM Opportunity WHERE AccountId != null AND Location_count__c = null")"
echo "BLANK SAMPLE $(q "SELECT Name, Account.Name, Account.Account_Level__c, Account.Root_Account__c, CreatedDate FROM Opportunity WHERE AccountId != null AND Location_count__c = null ORDER BY CreatedDate DESC LIMIT 6" | jq -c '[.[] | [.Name, .Account.Name, .Account.Account_Level__c, (.Account.Root_Account__c != null), .CreatedDate[0:10]]]')"
echo "QUOTE VS OPP $(q "SELECT QuoteNumber, Location_count__c, Opportunity.Location_count__c FROM Quote WHERE OpportunityId != null ORDER BY CreatedDate DESC LIMIT 200" | jq -c '[.[] | select(.Location_count__c != .Opportunity.Location_count__c) | [.QuoteNumber, .Location_count__c, .Opportunity.Location_count__c]] | .[0:10]')"
echo "PLAN ASSETS $(n "SELECT COUNT() FROM Asset WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT')"), linked to a contract $(n "SELECT COUNT() FROM Asset WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') AND Id IN (SELECT AssetId FROM AssetContractRelationship)")"
echo "ACTIVATED CONTRACTS no end date $(n "SELECT COUNT() FROM Contract WHERE Status = 'Activated' AND EndDate = null"), ended $(n "SELECT COUNT() FROM Contract WHERE Status = 'Activated' AND EndDate < TODAY")"
echo "ACCOUNTS non-corporate without root $(q "SELECT Name, Account_Level__c FROM Account WHERE Account_Level__c != 'Corporate' AND Account_Level__c != null AND Root_Account__c = null LIMIT 5" | jq -c '[.[] | [.Name, .Account_Level__c]]')"
echo "OPP WITH ASSETS $(q "SELECT Name, Account.Name, Location_count__c, CreatedDate FROM Opportunity WHERE AccountId IN (SELECT AccountId FROM Asset WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT')) ORDER BY CreatedDate DESC LIMIT 8" | jq -c '[.[] | [.Name, .Account.Name, .Location_count__c, .CreatedDate[0:10]]]')"
echo "ASSET QTY BY ROOT $(q "SELECT Account.Root_Account__r.Name r, Account.Name a, SUM(CurrentQuantity) s FROM Asset WHERE Product2.ProductCode IN ('MB-STR','MB-ACC','MB-ULT') GROUP BY Account.Root_Account__r.Name, Account.Name LIMIT 10")"
